-- Affiliate (代理) program. Anyone with an account can become an affiliate
-- via /aff; they get a unique slug used as ?ref=<slug> in their share link,
-- and earn a percentage of attributed orders.
--
-- Identity follows the rest of the customer side: email is the join key
-- (no users table). Slug is a short URL-safe random string generated by the
-- signup API (8 hex chars; uniqueness is enforced here).
--
-- The ledger (affiliate_ledger_entries) is the single source of truth for
-- accrued balance: lifetime balance = SUM(delta_cents). Entries are
-- append-only — never UPDATE/DELETE; corrections are new opposing rows
-- (commission_reversed, payout_reversed, adjustment).
--
-- "Available to settle" is computed at read time as
--   lifetime - (commission_earned/reversed rows where occurred_at is within
--   the last 30 days)
-- so the 30-day refund-safety lock is enforced at the read site instead of
-- via a separate "pending"→"available" state machine.

CREATE TABLE affiliates (
  id              TEXT PRIMARY KEY,
  email           TEXT UNIQUE NOT NULL,
  slug            TEXT UNIQUE NOT NULL,
  commission_pct  REAL NOT NULL DEFAULT 0.15,
  payout_method   TEXT,
  payout_account  TEXT,
  status          TEXT NOT NULL DEFAULT 'active'
                    CHECK (status IN ('active', 'suspended')),
  notes           TEXT,
  created_at      INTEGER NOT NULL DEFAULT (unixepoch() * 1000),
  updated_at      INTEGER NOT NULL DEFAULT (unixepoch() * 1000)
);

CREATE INDEX idx_affiliates_email ON affiliates(email);

CREATE TABLE affiliate_ledger_entries (
  id                  TEXT PRIMARY KEY,
  affiliate_id        TEXT NOT NULL REFERENCES affiliates(id),
  occurred_at         INTEGER NOT NULL,
  kind                TEXT NOT NULL CHECK (kind IN (
                        'commission_earned',
                        'commission_reversed',
                        'payout',
                        'payout_reversed',
                        'adjustment'
                      )),
  delta_cents         INTEGER NOT NULL,
  balance_after_cents INTEGER NOT NULL,
  order_id            TEXT,
  payout_id           TEXT,
  description         TEXT NOT NULL,
  created_at          INTEGER NOT NULL DEFAULT (unixepoch() * 1000)
);

CREATE INDEX idx_ledger_affiliate
  ON affiliate_ledger_entries(affiliate_id, occurred_at DESC);

CREATE TABLE payouts (
  id              TEXT PRIMARY KEY,
  affiliate_id    TEXT NOT NULL REFERENCES affiliates(id),
  amount_cents    INTEGER NOT NULL,
  method          TEXT NOT NULL,
  external_ref    TEXT,
  status          TEXT NOT NULL
                    CHECK (status IN ('pending', 'paid', 'failed')),
  initiated_at    INTEGER NOT NULL,
  completed_at    INTEGER,
  notes           TEXT,
  created_at      INTEGER NOT NULL DEFAULT (unixepoch() * 1000)
);

CREATE INDEX idx_payouts_affiliate ON payouts(affiliate_id, created_at DESC);

-- Order-level attribution snapshot. affiliate_slug is the slug captured from
-- the `lool_ref` cookie at order creation; attribution_at is when that cookie
-- was originally written (for audit / dispute resolution).
-- Soft reference (no FK to affiliates.slug) so the order's historical record
-- survives if an affiliate is later removed.
ALTER TABLE orders ADD COLUMN affiliate_slug TEXT;
ALTER TABLE orders ADD COLUMN attribution_at INTEGER;
